package com.braseiro.pathfinder2e;

import android.content.ContentValues;
import android.database.sqlite.SQLiteDatabase;
import org.json.JSONArray;
import org.json.JSONObject;
import java.util.Locale;
import java.util.Random;

/** Deterministic playable tactical geometry generated from the current scene, not a decorative image. */
public final class ProceduralTacticalSceneGenerator {
    private final AppDb db;public ProceduralTacticalSceneGenerator(AppDb database){db=database;AppDb.ensureSixZeroSchema(db.getWritableDatabase());}
    public synchronized JSONObject ensureForCurrentScene(){JSONObject scene=db.getSceneState();String location=scene.optString("location","Cena");String hex=scene.optString("hex_id");String env=inferEnvironment(scene);String key="scene:"+db.getActiveMapProfile()+":"+Integer.toHexString((location+"|"+hex+"|"+env).hashCode());JSONObject existing=db.queryOne("SELECT * FROM tactical_scenes WHERE world_profile=? AND scene_key=?",new String[]{db.getActiveMapProfile(),key});if(existing.length()>0)return existing;int seed=(db.getActiveMapProfile()+"|"+location+"|"+hex).hashCode();Random r=new Random(seed);int w=12,h=8;JSONArray obstacles=new JSONArray(),features=new JSONArray(),cover=new JSONArray(),entries=new JSONArray(),zones=new JSONArray();try{zones.put(new JSONObject().put("name","Companhia").put("x1",0).put("y1",0).put("x2",3).put("y2",h));zones.put(new JSONObject().put("name","Contato").put("x1",4).put("y1",0).put("x2",7).put("y2",h));zones.put(new JSONObject().put("name","Adversários").put("x1",8).put("y1",0).put("x2",w).put("y2",h));int n=env.equals("interior")?12:8;for(int i=0;i<n;i++){int x=1+r.nextInt(w-2),y=1+r.nextInt(h-2);String type=featureType(env,r);JSONObject o=new JSONObject().put("x",x).put("y",y).put("type",type).put("blocks_movement",type.matches("wall|tree|rock|crate|pillar")).put("cover",type.matches("tree|rock|crate|wall|pillar")?"half":"none");obstacles.put(o);if(!"none".equals(o.optString("cover")))cover.put(o);}features.put(new JSONObject().put("type",env).put("label",environmentLabel(env)));entries.put(new JSONObject().put("side","party").put("x",1).put("y",h/2));entries.put(new JSONObject().put("side","enemy").put("x",w-2).put("y",h/2));ContentValues v=new ContentValues();v.put("world_profile",db.getActiveMapProfile());v.put("scene_key",key);v.put("location",location);v.put("hex_id",hex);v.put("environment",env);v.put("width_cells",w);v.put("height_cells",h);v.put("seed",seed);v.put("zones_json",zones.toString());v.put("obstacles_json",obstacles.toString());v.put("features_json",features.toString());v.put("cover_json",cover.toString());v.put("hazards_json","[]");v.put("entry_points_json",entries.toString());v.put("source_context_json",new JSONObject().put("scene",scene).toString());v.put("status","ready");v.put("created_at",System.currentTimeMillis());v.put("updated_at",System.currentTimeMillis());db.getWritableDatabase().insertWithOnConflict("tactical_scenes",null,v,SQLiteDatabase.CONFLICT_REPLACE);}catch(Exception ignored){AppLog.ignored("ProceduralTacticalSceneGenerator","Falha tolerada na camada 6.0.",ignored);}return db.queryOne("SELECT * FROM tactical_scenes WHERE world_profile=? AND scene_key=?",new String[]{db.getActiveMapProfile(),key});}
    public JSONObject current(){return db.queryOne("SELECT * FROM tactical_scenes WHERE world_profile=? ORDER BY updated_at DESC,id DESC LIMIT 1",new String[]{db.getActiveMapProfile()});}
    public JSONObject regenerate(){JSONObject scene=db.getSceneState();String location=scene.optString("location","Cena"),hex=scene.optString("hex_id"),env=inferEnvironment(scene);db.getWritableDatabase().delete("tactical_scenes","world_profile=? AND location=? AND hex_id=?",new String[]{db.getActiveMapProfile(),location,hex});return ensureForCurrentScene();}
    public JSONObject context(){JSONObject o=new JSONObject();try{o.put("current",ensureForCurrentScene()).put("contract","Geometria tática é jogável e local. Obstáculos/cover visuais não criam regra mecânica fora do motor de regras.");}catch(Exception ignored){AppLog.ignored("ProceduralTacticalSceneGenerator","Falha tolerada na camada 6.0.",ignored);}return o;}
    private static String inferEnvironment(JSONObject s){String t=(s.optString("location")+" "+s.optString("danger")+" "+s.optString("weather")).toLowerCase(Locale.ROOT);if(t.matches(".*(taverna|casa|castelo|templo|cripta|masmorra|dungeon|sala|torre|interior).*"))return "interior";if(t.matches(".*(floresta|bosque|mata|selva).*"))return "forest";if(t.matches(".*(ruína|ruina|pedra|montanha|caverna).*"))return "ruins";if(t.matches(".*(cidade|vila|rua|mercado|porto).*"))return "urban";if(t.matches(".*(rio|pântano|pantano|lago|costa).*"))return "wetland";return "open";}
    private static String featureType(String env,Random r){String[] a;if("interior".equals(env))a=new String[]{"wall","crate","pillar","table"};else if("forest".equals(env))a=new String[]{"tree","bush","rock","fallen_log"};else if("ruins".equals(env))a=new String[]{"rock","wall","pillar","rubble"};else if("urban".equals(env))a=new String[]{"crate","cart","wall","stall"};else if("wetland".equals(env))a=new String[]{"water","reed","rock","mud"};else a=new String[]{"rock","bush","ditch","crate"};return a[r.nextInt(a.length)];}
    private static String environmentLabel(String e){return e.equals("forest")?"Floresta":e.equals("interior")?"Interior":e.equals("ruins")?"Ruínas":e.equals("urban")?"Área urbana":e.equals("wetland")?"Terreno úmido":"Terreno aberto";}
}
